// cv::imread passes the path through the narrow CRT API, so any non-ASCII directory (a Chinese
// project folder, for instance) makes it fail with "can't open/read file". Read the bytes with the
// wide-character stream and decode from memory instead.
cv::Mat loadImage(const std::wstring& path){std::ifstream f(fs::path(path),std::ios::binary);if(!f)return{};std::vector<unsigned char> b((std::istreambuf_iterator<char>(f)),std::istreambuf_iterator<char>());if(b.empty())return{};return cv::imdecode(b,cv::IMREAD_COLOR);}
