void writeTextFile(const std::wstring& p,const std::string& s){std::ofstream f(fs::path(p),std::ios::binary);f.write(s.data(),(std::streamsize)s.size());}
std::string wideUtf8(const std::wstring& s){int n=WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0,nullptr,nullptr);std::string u(n,'\0');if(n)WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),u.data(),n,nullptr,nullptr);return u;}
