bool startTranslator(){translatorIdleSecs.store(0);killStrayTranslators();auto d=translatorCache();auto exe=d/L"mtranserver.exe";if(!fs::exists(exe)&&!extractResource(100,exe))return false;const std::pair<int,const wchar_t*> files[]={{101,L"mtran_models/en_zh-Hans/lex.50.50.enzh.s2t.bin"},{102,L"mtran_models/en_zh-Hans/model.enzh.intgemm.alphas.bin"},{103,L"mtran_models/en_zh-Hans/srcvocab.enzh.spm"},{104,L"mtran_models/en_zh-Hans/trgvocab.enzh.spm"},{105,L"mtran_models/zh-Hans_en/lex.50.50.zhen.s2t.bin"},{106,L"mtran_models/zh-Hans_en/model.zhen.intgemm.alphas.bin"},{107,L"mtran_models/zh-Hans_en/vocab.zhen.spm"}};auto records=d/L"mtran_config/records.json";if(!fs::exists(records))extractResource(108,records);for(auto& x:files){auto p=d/x.second;if(!fs::exists(p)&&!extractResource(x.first,p))return false;}if(translatorReady())return true;std::wstring cmd=L"\""+exe.wstring()+L"\" --host 127.0.0.1 --port 8989 --model-dir \""+(d/L"mtran_models").wstring()+L"\" --config-dir \""+(d/L"mtran_config").wstring()+L"\" --no-ui --offline --no-check-update --no-log-console --log-level error --worker-idle-timeout 3 --workers-per-language 1";std::vector<wchar_t> buf(cmd.begin(),cmd.end());buf.push_back(0);STARTUPINFOW si{};si.cb=sizeof(si);PROCESS_INFORMATION pi{};if(!CreateProcessW(nullptr,buf.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,d.wstring().c_str(),&si,&pi))return false;CloseHandle(pi.hThread);translatorProcess=pi.hProcess;for(int i=0;i<60&&!translatorReady();++i)Sleep(100);return translatorReady();}
