// Drain queued paints before the snapshot so the re-hide actually reaches the screen; called from
// the GUI thread only, where PeekMessageW does not steal messages from GetMessageW.
void flushMsg(){MSG msg{};for(int i=0;i<512&&PeekMessageW(&msg,nullptr,0,0,PM_REMOVE);++i){TranslateMessage(&msg);DispatchMessageW(&msg);}}
