// Crop the already-taken snapshot into BGRA pixels. The previous code wrote every capture to the
// shared %TEMP%\ppocr_capture.bmp, so a second capture - or the "clear temp files" action, which
// deletes that very path - could hand the OCR thread a stale or empty file and produce text that
// belongs to a different region than the one selected.
void cropToMat(const RECT&r,cv::Mat&out){out.release();int w=r.right-r.left,h=r.bottom-r.top;if(w<1||h<1||!st.bmp)return;
HDC screen=CreateDCW(L"DISPLAY",nullptr,nullptr,nullptr);bool ownScr=screen!=nullptr;if(!ownScr)screen=GetDC(nullptr);
HDC m=CreateCompatibleDC(screen),src=CreateCompatibleDC(screen);auto os=SelectObject(src,st.bmp);
HBITMAP b=CreateCompatibleBitmap(screen,w,h);auto om=SelectObject(m,b);
if(!BitBlt(m,0,0,w,h,src,r.left,r.top,SRCCOPY))BitBlt(m,0,0,w,h,src,r.left,r.top,SRCCOPY);
SelectObject(src,os);SelectObject(m,om);
BITMAPINFO bi{};bi.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bi.bmiHeader.biWidth=w;bi.bmiHeader.biHeight=-h;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;bi.bmiHeader.biCompression=BI_RGB;
out=cv::Mat(h,w,CV_8UC4);GetDIBits(screen,b,0,h,out.data,&bi,DIB_RGB_COLORS);
cv::Mat bgr;cv::cvtColor(out,bgr,cv::COLOR_BGRA2BGR);out=bgr;
DeleteObject(b);DeleteDC(src);DeleteDC(m);if(ownScr)DeleteDC(screen);else ReleaseDC(nullptr,screen);}
// Same shape as cropToMat but returns a standalone BMP carrier, used by the CLI diagnostics and by
// the opt-in debug dump. Off by default so the app keeps its "no persistent cache" promise; set
// PPOCR_DEBUG=1 to have the exact pixels that were fed to the engine written next to the text.
bool debugDumpEnabled(){wchar_t v[8]{};DWORD n=GetEnvironmentVariableW(L"PPOCR_DEBUG",v,8);return n>0&&v[0]==L'1';}
// Serialise a rectangle of the snapshot as a standalone BMP. Only the diagnostics paths call this.
bool cropToBmpBytes(const RECT&r,std::vector<unsigned char>&bytes){bytes.clear();int w=r.right-r.left,h=r.bottom-r.top;if(w<1||h<1||!st.bmp)return false;
HDC screen=CreateDCW(L"DISPLAY",nullptr,nullptr,nullptr);bool ownScr=screen!=nullptr;if(!ownScr)screen=GetDC(nullptr);
HDC m=CreateCompatibleDC(screen),src=CreateCompatibleDC(screen);auto os=SelectObject(src,st.bmp);
HBITMAP b=CreateCompatibleBitmap(screen,w,h);auto om=SelectObject(m,b);BitBlt(m,0,0,w,h,src,r.left,r.top,SRCCOPY);
SelectObject(src,os);SelectObject(m,om);
BITMAPINFO bi{};bi.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bi.bmiHeader.biWidth=w;bi.bmiHeader.biHeight=-h;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;bi.bmiHeader.biCompression=BI_RGB;
std::vector<unsigned char> px((size_t)w*h*4);GetDIBits(screen,b,0,h,px.data(),&bi,DIB_RGB_COLORS);
BITMAPFILEHEADER fh{};fh.bfType=0x4d42;fh.bfOffBits=sizeof(fh)+sizeof(BITMAPINFOHEADER);fh.bfSize=fh.bfOffBits+(DWORD)px.size();
bytes.resize(fh.bfSize);memcpy(bytes.data(),&fh,sizeof fh);memcpy(bytes.data()+sizeof fh,&bi.bmiHeader,sizeof bi.bmiHeader);memcpy(bytes.data()+fh.bfOffBits,px.data(),px.size());
DeleteObject(b);DeleteDC(src);DeleteDC(m);if(ownScr)DeleteDC(screen);else ReleaseDC(nullptr,screen);return true;}
