bool regExists(const wchar_t* sub,const wchar_t* name){HKEY k{};bool ok=RegOpenKeyExW(HKEY_CURRENT_USER,sub,0,KEY_READ,&k)==ERROR_SUCCESS&&RegQueryValueExW(k,name,nullptr,nullptr,nullptr,nullptr)==ERROR_SUCCESS;if(k)RegCloseKey(k);return ok;}
void writeReg(const wchar_t* name,bool on){HKEY k{};if(RegCreateKeyExW(HKEY_CURRENT_USER,RUN_KEY,0,nullptr,0,KEY_SET_VALUE,nullptr,&k,nullptr)!=ERROR_SUCCESS)return;if(on){wchar_t e[MAX_PATH]{};GetModuleFileNameW(nullptr,e,MAX_PATH);std::wstring s=L"\""+std::wstring(e)+L"\"";RegSetValueExW(k,name,0,REG_SZ,(BYTE*)s.c_str(),(DWORD)((s.size()+1)*sizeof(wchar_t)));}else RegDeleteValueW(k,name);RegCloseKey(k);}
void loadSettings(){startupEnabled=regExists(RUN_KEY,RUN_VALUE);startMinimized=false;HKEY k{};if(RegOpenKeyExW(HKEY_CURRENT_USER,SETTINGS_KEY,0,KEY_READ,&k)==ERROR_SUCCESS){DWORD v=0,n=4,t=0;if(RegQueryValueExW(k,L"StartMinimized",0,&t,(BYTE*)&v,&n)==ERROR_SUCCESS)startMinimized=(v!=0);v=0;n=4;if(RegQueryValueExW(k,L"HotkeyVk",0,&t,(BYTE*)&v,&n)==ERROR_SUCCESS)hotVk=v;v=0;n=4;if(RegQueryValueExW(k,L"HotkeyMods",0,&t,(BYTE*)&v,&n)==ERROR_SUCCESS&&v)hotMods=v;wchar_t mb[256]{};n=sizeof(mb);if(RegQueryValueExW(k,L"TranslationModel",0,&t,(BYTE*)mb,&n)==ERROR_SUCCESS)selectedModel=mb;RegCloseKey(k);}HKEY r{};if(RegOpenKeyExW(HKEY_CURRENT_USER,RUN_KEY,0,KEY_SET_VALUE,&r)==ERROR_SUCCESS){RegDeleteValueW(r,L"PP-OCRv6 Start Minimized");RegCloseKey(r);}}
void saveModel(){HKEY k{};if(RegCreateKeyExW(HKEY_CURRENT_USER,SETTINGS_KEY,0,nullptr,0,KEY_SET_VALUE,nullptr,&k,nullptr)==ERROR_SUCCESS){RegSetValueExW(k,L"TranslationModel",0,REG_SZ,(BYTE*)selectedModel.c_str(),(DWORD)((selectedModel.size()+1)*sizeof(wchar_t)));RegCloseKey(k);}}
void saveHotkey(){HKEY k{};if(RegCreateKeyExW(HKEY_CURRENT_USER,SETTINGS_KEY,0,nullptr,0,KEY_SET_VALUE,nullptr,&k,nullptr)==ERROR_SUCCESS){DWORD a=hotVk,b=hotMods;RegSetValueExW(k,L"HotkeyVk",0,REG_DWORD,(BYTE*)&a,4);RegSetValueExW(k,L"HotkeyMods",0,REG_DWORD,(BYTE*)&b,4);RegCloseKey(k);}}
HBITMAP desktop(){int x=GetSystemMetrics(SM_XVIRTUALSCREEN),y=GetSystemMetrics(SM_YVIRTUALSCREEN),w=GetSystemMetrics(SM_CXVIRTUALSCREEN),h=GetSystemMetrics(SM_CYVIRTUALSCREEN);
// Capture through a DC created for the display device, not GetDC(NULL): the latter returns the
// primary monitor's DC, so on mixed-DPI setups CreateCompatibleBitmap and the delegated
// GetSystemMetrics sizes disagree with the requested rectangle and BitBlt quietly produces a
// black, cropped or stale snapshot.
HDC screen=CreateDCW(L"DISPLAY",nullptr,nullptr,nullptr);
bool ownScr=screen!=nullptr;if(!ownScr)screen=GetDC(nullptr);
HDC m=CreateCompatibleDC(screen);HBITMAP b=CreateCompatibleBitmap(screen,w,h);auto o=SelectObject(m,b);
if(!BitBlt(m,0,0,w,h,screen,x,y,SRCCOPY|CAPTUREBLT)){BitBlt(m,0,0,w,h,screen,x,y,SRCCOPY);}
SelectObject(m,o);DeleteDC(m);if(ownScr)DeleteDC(screen);else ReleaseDC(nullptr,screen);return b;}
// Hide everything this process owns before grabbing the desktop. Grabbing first and hiding
// afterwards captures yesterday's result / settings / main window inside the snapshot, so the
// recognised text belongs to that stale window rather than to the region the user selected.
void captureDesktop(){closeOtherWindows();ShowWindow(mainWnd,SW_HIDE);flushMsg();Sleep(150);
for(int i=0;i<100&&IsWindowVisible(mainWnd);++i){ShowWindow(mainWnd,SW_HIDE);Sleep(10);}
freeBmp();st.bmp=desktop();}
HBITMAP makeDimmed(HBITMAP source,int w,int h){if(!source)return nullptr;HDC screen=GetDC(nullptr),src=CreateCompatibleDC(screen),dst=CreateCompatibleDC(screen);HBITMAP out=CreateCompatibleBitmap(screen,w,h);auto oldSrc=SelectObject(src,source);auto oldDst=SelectObject(dst,out);BitBlt(dst,0,0,w,h,src,0,0,SRCCOPY);HBRUSH shade=CreateSolidBrush(RGB(40,40,40));RECT r{0,0,w,h};HDC layer=CreateCompatibleDC(screen);HBITMAP layerBmp=CreateCompatibleBitmap(screen,w,h);auto oldLayer=SelectObject(layer,layerBmp);FillRect(layer,&r,shade);BLENDFUNCTION blend{AC_SRC_OVER,0,105,0};AlphaBlend(dst,0,0,w,h,layer,0,0,w,h,blend);SelectObject(layer,oldLayer);DeleteObject(layerBmp);DeleteDC(layer);DeleteObject(shade);SelectObject(src,oldSrc);SelectObject(dst,oldDst);DeleteDC(src);DeleteDC(dst);ReleaseDC(nullptr,screen);return out;}
RECT sel(){return{std::min(st.a.x,st.b.x),std::min(st.a.y,st.b.y),std::max(st.a.x,st.b.x),std::max(st.a.y,st.b.y)};}
std::wstring ocr(const fs::path& image){cv::Mat mat=loadImage(image.wstring());if(mat.empty())return L"无法读取截图";std::wstring t;ocrMat(mat,t);return t;}
// Engine entry point on raw pixels. Keeping the whole path in memory removes the shared temp file
// that used to be written, read and deleted concurrently by the capture thread, the OCR thread and
// the "clear temp files" action.
void ocrMatEx(const cv::Mat& mat,std::wstring& out,const std::string& cfgPath){try{auto md=ocrCache()/L"ppocrv6_tiny";const wchar_t*n[]={L"PP_OCRv6_tiny_det.param",L"PP_OCRv6_tiny_det.bin",L"PP_OCRv6_tiny_rec.param",L"PP_OCRv6_tiny_rec.bin",L"PP_LCNet_x0_25_textline_ori.param",L"PP_LCNet_x0_25_textline_ori.bin",L"ppocr_keys_v6.txt"};for(auto x:n)if(!fs::exists(md/x)){out=L"PP-OCRv6 模型文件缺失："+std::wstring(x);return;}if(mat.empty()){out=L"无法读取截图";return;}OCR::OCREngine e;if(!e.Initialize(cfgPath)){out=L"PP-OCRv6 模型加载失败";return;}auto rs=e.Run(mat);struct I{const OCR::OCRResult*r;int l,rr,t,b,y;};std::vector<I> a;for(auto&x:rs){if(x.line.text.empty()||x.box.points.empty())continue;int l=x.box.points[0].x,rr=l,t=x.box.points[0].y,b=t;for(auto&p:x.box.points){l=(std::min)(l,p.x);rr=(std::max)(rr,p.x);t=(std::min)(t,p.y);b=(std::max)(b,p.y);}a.push_back({&x,l,rr,t,b,(t+b)/2});}std::sort(a.begin(),a.end(),[](const I&x,const I&y){int h=(std::max)(x.b-x.t,y.b-y.t);return std::abs(x.y-y.y)<=h/2?x.l<y.l:x.y<y.y;});std::string s;int pr=-1,ph=0,py=-1;for(auto&x:a){int h=(std::max)(1,x.b-x.t);if(!s.empty()){if(py>=0&&std::abs(x.y-py)>(std::max)(h,ph)/2)s+="\n";else if(x.l-pr>h/3)s+=" ";}s+=x.r->line.text;pr=x.rr;ph=h;py=x.y;}if(s.empty())s="未识别到文字";int z=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0);std::wstring w(z,L' ');MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),w.data(),z);out=w;}catch(...){out=L"PP-OCRv6 识别发生异常";}}
void ocrMat(const cv::Mat& mat,std::wstring& out){ocrMatEx(mat,out,(ocrCache()/L"ppocrv6_config.json").string());}
std::wstring displayText(const std::wstring& text){std::wstring out;out.reserve(text.size()+16);for(size_t i=0;i<text.size();++i){if(text[i]==L"\\"[0]&&i+1<text.size()&&text[i+1]==L"n"[0]){out+=L"\r\n";++i;continue;}if(text[i]==L"\r"[0]){if(i+1<text.size()&&text[i+1]==L"\n"[0])++i;out+=L"\r\n";continue;}if(text[i]==L"\n"[0]){out+=L"\r\n";continue;}out+=text[i];}return out;}
std::string jsonEscape(const std::wstring&s){int n=WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0,nullptr,nullptr);std::string u(n,'\0');WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),u.data(),n,nullptr,nullptr);std::string o;const char hex[]="0123456789abcdef";for(unsigned char c:u){if(c=='\\'||c=='"'){o+='\\';o+=c;}else if(c=='\b')o+="\\b";else if(c=='\f')o+="\\f";else if(c=='\n')o+="\\n";else if(c=='\r')o+="\\r";else if(c=='\t')o+="\\t";else if(c<0x20){o+="\\u00";o+=hex[c>>4];o+=hex[c&15];}else o+=c;}return o;}
std::wstring utf8(const std::string&s);
std::wstring jsonResult(const std::string& raw){auto key=raw.find("\"result\"");if(key==std::string::npos)return L"";auto colon=raw.find(':',key+8);auto begin=colon==std::string::npos?std::string::npos:raw.find('"',colon+1);if(begin==std::string::npos)return L"";std::string value;for(size_t i=begin+1;i<raw.size();++i){char c=raw[i];if(c=='"')return utf8(value);if(c!='\\'){value+=c;continue;}if(++i>=raw.size())return L"";char e=raw[i];if(e=='n')value+='\n';else if(e=='r')value+='\r';else if(e=='t')value+='\t';else if(e=='b')value+='\b';else if(e=='f')value+='\f';else if(e=='"'||e=='\\'||e=='/')value+=e;else return L"";}return L"";}
std::wstring utf8(const std::string&s){int n=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0);std::wstring w(n,L' ');MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),w.data(),n);return w;}
std::wstring translateLocal(const std::wstring& text,const std::wstring& source,const std::wstring& target,bool retried=false){if(translationCancel.load())return L"翻译已取消";if(text.empty()||source==target)return text;if(!translatorReady()&&!startTranslator())return L"翻译引擎启动失败，请关闭程序后重新打开。";HINTERNET ses=WinHttpOpen(L"PP-OCRv6-Desktop",WINHTTP_ACCESS_TYPE_NO_PROXY,nullptr,nullptr,0);if(!ses)return L"无法启动翻译连接";WinHttpSetTimeouts(ses,3000,3000,15000,60000);HINTERNET con=WinHttpConnect(ses,L"127.0.0.1",8989,0);std::string body="{\"from\":\""+jsonEscape(source)+"\",\"to\":\""+jsonEscape(target)+"\",\"text\":\""+jsonEscape(text)+"\",\"html\":false}";HINTERNET req=con?WinHttpOpenRequest(con,L"POST",L"/translate",nullptr,nullptr,nullptr,0):nullptr;std::wstring out;DWORD status=0,statusSize=sizeof(status);if(req&&WinHttpAddRequestHeaders(req,L"Content-Type: application/json; charset=utf-8\r\n",-1,WINHTTP_ADDREQ_FLAG_ADD)&&WinHttpSendRequest(req,nullptr,0,(LPVOID)body.data(),(DWORD)body.size(),(DWORD)body.size(),0)&&WinHttpReceiveResponse(req,nullptr)){WinHttpQueryHeaders(req,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,nullptr,&status,&statusSize,nullptr);std::string raw;for(;;){DWORD n=0;if(!WinHttpQueryDataAvailable(req,&n)||!n)break;std::string b(n,'\0');DWORD got=0;if(!WinHttpReadData(req,b.data(),n,&got))break;raw.append(b.data(),got);}if(status>=200&&status<300)out=jsonResult(raw);if(out.empty()&&status>=400)out=L"翻译服务返回错误（HTTP "+std::to_wstring(status)+L"）。";}if(req)WinHttpCloseHandle(req);if(con)WinHttpCloseHandle(con);WinHttpCloseHandle(ses);if(!out.empty())return out;if(!retried&&!translationCancel.load()){stopTranslator();if(startTranslator())return translateLocal(text,source,target,true);}return L"翻译失败：翻译服务没有返回可用内容。";}


std::wstring translatePreserveBreaks(const std::wstring& text,const std::wstring& source,const std::wstring& target){if(text.empty())return L"";if(translationCancel.load())return L"翻译已取消";return translateLocal(text,source,target);}
// Copy arbitrary text to the clipboard. Used by the CLI capture path, which has no edit control.
void setClipboardText(const std::wstring&s){if(!OpenClipboard(mainWnd))return;EmptyClipboard();HGLOBAL h=GlobalAlloc(GMEM_MOVEABLE,(s.size()+1)*sizeof(wchar_t));if(h){memcpy(GlobalLock(h),s.c_str(),(s.size()+1)*sizeof(wchar_t));GlobalUnlock(h);SetClipboardData(CF_UNICODETEXT,h);}CloseClipboard();}
