// Regression harness. --ocrtest runs the recogniser on a given image at several detection
// resolutions so a capture can be replayed and compared against the text it produced, without any
// GUI interaction. --capture grabs the desktop exactly like the overlay does (own windows hidden)
// and writes both the snapshot and the recognised text, which is how the "text does not match the
// screenshot" defect is proved or disproved.
// Replace the numeric value of a JSON key without pulling in a parser. Only used by the CLI test
// mode, on a throwaway copy of the config, so the installed settings are never rewritten.
std::string patchNumber(const std::string& cfg,const std::string& key,int value){size_t k=cfg.find("\""+key+"\"");if(k==std::string::npos)return cfg;size_t c=cfg.find(':',k);if(c==std::string::npos)return cfg;size_t b=c+1;while(b<cfg.size()&&(cfg[b]==' '||cfg[b]=='\t'))++b;size_t e=b;while(e<cfg.size()&&cfg[e]>='0'&&cfg[e]<='9')++e;if(e==b)return cfg;std::string s=cfg;s.replace(b,e-b,std::to_string(value));return s;}
int runCliMode(const std::wstring& mode,int argc,wchar_t** argv){
SetCurrentDirectoryW(ocrCache().parent_path().c_str());ensureOcrAssets();
auto outDir=ocrCache().parent_path()/L"logs";std::error_code ec;fs::create_directories(outDir,ec);
if(mode==L"--ocrtest"){if(argc<3){wprintf(L"usage: --ocrtest IMAGE\n");return 2;}std::wstring p=argv[2];cv::Mat mat=loadImage(p);if(mat.empty()){wprintf(L"cannot read %ls\n",p.c_str());return 3;}
wprintf(L"input %dx%d\n",mat.cols,mat.rows);
std::wstring baseCfg=(ocrCache()/L"ppocrv6_config.json").wstring();std::string base=readTextFile(baseCfg);
// Sweep the detection resolution so the caller can see whether a mismatch between the recognised
// text and the picture is a resolution/scale artefact or a genuine capture problem.
for(int side:{(int)0,768,1024,1536}){cv::Mat in=mat;if(side>0){const int longest=(std::max)(mat.cols,mat.rows);if(longest>side){double r=(double)side/longest;cv::resize(mat,in,cv::Size(),r,r,cv::INTER_AREA);}}
std::wstring cfg=baseCfg;if(side>0&&!base.empty()){cfg=(outDir/(L"ocrtest_cfg.txt")).wstring();writeTextFile(cfg,patchNumber(base,"max_side_len",side));}
std::wstring text;ocrMatEx(in,text,wideUtf8(cfg));
wprintf(L"[max_side_len=%d in=%dx%d] %ls\n",side?side:1024,in.cols,in.rows,text.c_str());
writeTextFile(outDir/(std::to_wstring(side?side:1024)+L"_ocrtest.txt"),wideUtf8(text));}
return 0;}
if(mode==L"--capture"){loadSettings();updateBrushes();
// Create and SHOW the main window first. This is the decisive regression test for the original
// defect: if the snapshot still contains this window, the "recognised text does not match the
// picture" symptom is back.
HINSTANCE hi=GetModuleHandleW(nullptr);WNDCLASSEXW c{};c.cbSize=sizeof(c);c.hInstance=hi;c.lpszClassName=MAIN_CLASS;c.lpfnWndProc=mainProc;RegisterClassExW(&c);
mainWnd=CreateWindowW(MAIN_CLASS,L"PP-OCRv6 Desktop",WS_OVERLAPPED|WS_CAPTION|WS_SYSMENU,60,60,760,420,nullptr,nullptr,hi,nullptr);
ShowWindow(mainWnd,SW_SHOW);SetForegroundWindow(mainWnd);for(int i=0;i<60;++i){MSG mm{};while(PeekMessageW(&mm,nullptr,0,0,PM_REMOVE)){TranslateMessage(&mm);DispatchMessageW(&mm);}Sleep(15);}
bool visibleBefore=IsWindowVisible(mainWnd)!=0;captureDesktop();bool visibleAfter=IsWindowVisible(mainWnd)!=0;
if(!st.bmp)return 5;int x=GetSystemMetrics(SM_XVIRTUALSCREEN),y=GetSystemMetrics(SM_YVIRTUALSCREEN),w=GetSystemMetrics(SM_CXVIRTUALSCREEN),h=GetSystemMetrics(SM_CYVIRTUALSCREEN);RECT full{0,0,w,h};
std::vector<unsigned char> d;if(!cropToBmpBytes(full,d))return 6;cv::Mat shot;cropToMat(full,shot);logDump(L"cli_capture",d,full,shot);
std::wstring text;ocrMat(shot,text);writeTextFile(outDir/L"cli_capture.txt",wideUtf8(text));setClipboardText(text);
wprintf(L"captured %dx%d (%d,%d) windowVisibleBefore=%d after=%d\n%ls\n",w,h,x,y,(int)visibleBefore,(int)visibleAfter,text.c_str());return 0;}
return 1;}
